            return value === undefined ? null : value;
        }
        catch (error) {
            return null;
        }
    },
    async set(key, value) {
        const api = bridge();
        if (!api || !api.storage) {
            memoryStore.set(key, value);
            return true;
        }
        try {
            await api.storage.set(key, value);
            return true;
        }
        catch (error) {
            return false;
        }
    },
    async remove(key) {
        const api = bridge();
        if (!api || !api.storage) {
            memoryStore.delete(key);
            return true;
